import java.util.*;
import java.io.*;

public class Variant2 {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long lmao = sc.nextLong();
        if (lmao >= N) {
            System.out.println(0);
        } else {
            int K = (int) lmao;
            int C = N - K;
            long[] factorials = new long[200001];
            long[] invFactorials = new long[200001];
            factorials[0] = 1;
            invFactorials[0] = 1;
            for (int i = 1; i <= 200000; i++) {
                factorials[i] = (factorials[i - 1] * i) % 998244353L;
                invFactorials[i] = modPow(factorials[i], 998244351L, 998244353L);
            }
            long res = modPow(C, N, 998244353L);
            for (int e = 1; e < C; e++) {
                long temp = modPow(C - e, N, 998244353L);
                temp = (temp * nCr(e, C, factorials, invFactorials)) % 998244353L;
                if (e % 2 == 1)
                    res = (res - temp + 998244353L) % 998244353L;
                else
                    res = (res + temp) % 998244353L;
            }
            res = (res * nCr(C, N, factorials, invFactorials)) % 998244353L;
            if (K > 0)
                res = (2 * res) % 998244353L;
            System.out.println(res);
        }
        sc.close();
    }

    static long nCr(int a, int b, long[] fact, long[] invFact) {
        return (((fact[b] * invFact[a]) % 998244353L) * invFact[b - a]) % 998244353L;
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1)
                result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}
